			rt.ArrayItem{
				key: 'In this case, WordPress caught an error with one of your plugins, %s.'
				val: '这次，WordPress 发现了您的插件造成的错误：%s。'
			},
			rt.ArrayItem{
				key: 'Howdy!\n\nWordPress has a built-in feature that detects when a plugin or theme causes a fatal error on your site, and notifies you with this automated email.\n###CAUSE###\nFirst, visit your website (###SITEURL###) and check for any visible issues. Next, visit the page where the error was caught (###PAGEURL###) and check for any visible issues.\n\n###SUPPORT###\n\nIf your site appears broken and you can\'t access your dashboard normally, WordPress now has a special "recovery mode". This lets you safely login to your dashboard and investigate further.\n\n###LINK###\n\nTo keep your site safe, this link will expire in ###EXPIRES###. Don\'t worry about that, though: a new link will be emailed to you if the error occurs again after it expires.\n\nWhen seeking help with this issue, you may be asked for some of the following information:\n###DEBUG###\n\n###DETAILS###'
				val: '您好：\n\nWordPress 从版本 5.2 开始，能够检测到您站点上的插件或主题造成了致命错误，并向您发送自动的通知邮件。\n###CAUSE###\n首先，访问您的站点（###SITEURL### ）并查看有无可见的问题。然后，访问发生错误的页面（###PAGEURL### ）并查看有无问题。\n\n###SUPPORT###\n\n如果您的站点看上去不正常，且您不能正常访问仪表盘，WordPress 现在有了特殊的「恢复模式」，能够让您安全地登录仪表盘并检查问题。\n\n###LINK###\n\n为了保障您的站点安全，此链接将在 ###EXPIRES### 后过期。请不用担心，如果在此之后错误再度发生，我们将向您发送新的链接。\n\n在寻求关于此问题的帮助时，您可能需要提供以下信息：\n###DEBUG###\n\n###DETAILS###'
			},
			rt.ArrayItem{
				key: 'Please contact your host for assistance with investigating this issue further.'
